    internal static int PtSf(byte[] src, int which) {
        // One field of the stream parsed from src (an indirect object).
        emon.Port.Cells ar = emon.Port.NewCells();
        int z = PtPrep(ar, src);
        int s = Pdflex.PlParseIndirect(src, ar, 0);
        int sd = Pdflex.PlStreamDict(ar, s);
        int lh = Pdflex.PlDictGet(ar, sd, Pdfnames.PnLength());
        if (z != 0) {
            return -1;
        }
        if (which == 0) {
            return Pdflex.PlObjnum(ar);
        }
        if (which == 1) {
            return Pdflex.PlObjgen(ar);
        }
        if (which == 2) {
            return Pdflex.PlKindOf(ar, s);
        }
        if (which == 3) {
            return Pdflex.PlStreamStart(ar, s);
        }
        if (which == 4) {
            return Pdflex.PlStreamLen(ar, s);
        }
        if (which == 5) {
            return Pdflex.PlStreamFlags(ar, s);
        }
        return Pdflex.PlIntValue(ar, lh);
    }
    [Xunit.Fact]
    public static void TestStreamFieldsOfAnIndirectObject() {
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 0), 7, "object number");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 1), 2, "generation");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 2), Pdflex.PlKStream(), "a stream");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 3), 29, "data starts after the end of line");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 4), 5, "five bytes");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 5), 0, "length trusted");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n"), 6), 5, "the dictionary");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 3>>\nstream\nhello\nendstream\nendobj\n"), 5), 1, "a wrong length is scanned");
        emon.Testport.AssertEq(PtSf(emon.Testport.TextBlob("7 2 obj\n<</Length 3>>\nstream\nhello\nendstream\nendobj\n"), 4), 5, "and the real length found");
    }
